function makeId(){ return crypto.randomUUID(); }
function newQuestion(type:QuestionType='single_choice'):Question {
  if(type==='single_choice'||type==='multiple_choice') return {id:makeId(),position:0,type,prompt:'Новый вопрос',points:1,data:{options:[{id:makeId(),text:'Вариант 1'},{id:makeId(),text:'Вариант 2'}],...(type==='single_choice'?{correctOptionId:''}:{correctOptionIds:[]})}};
  if(type==='true_false') return {id:makeId(),position:0,type,prompt:'Новое утверждение',points:1,data:{correct:true}};
  if(type==='fill_blank') return {id:makeId(),position:0,type,prompt:'Вставьте пропуск: ______',points:1,data:{accepted:['']}};
  if(type==='matching') return {id:makeId(),position:0,type,prompt:'Сопоставьте элементы.',points:2,data:{pairs:[{id:makeId(),left:'Термин',right:'Определение'}]}};
  if(type==='ordering') { const items=[{id:makeId(),text:'Шаг 1'},{id:makeId(),text:'Шаг 2'},{id:makeId(),text:'Шаг 3'}]; return {id:makeId(),position:0,type,prompt:'Расположите действия по порядку.',points:2,data:{items,correctOrderIds:items.map(x=>x.id)}}; }
  if(type==='numeric') return {id:makeId(),position:0,type,prompt:'Введите число.',points:1,data:{correct:0,tolerance:0}};
  return {id:makeId(),position:0,type,prompt:type==='code'?'Напишите код, решающий задачу.':'Напишите ответ.',points:2,data:{placeholder:'Введите ответ…',rubric:''}};
}
function duplicateQuestionModel(source:Question,position:number):Question{
  const clone=structuredClone(source); clone.id=makeId(); clone.position=position;
  if(clone.type==='single_choice'||clone.type==='multiple_choice'){
    const idMap=new Map<string,string>(); const options=(clone.data.options||[]).map((o:any)=>{const id=makeId();idMap.set(String(o.id),id);return {...o,id};}); clone.data.options=options;
    if(clone.type==='single_choice') clone.data.correctOptionId=idMap.get(String(source.data.correctOptionId||''))||'';
    else clone.data.correctOptionIds=(Array.isArray(source.data.correctOptionIds)?source.data.correctOptionIds:[]).map((id:string)=>idMap.get(String(id))).filter(Boolean);
  }
  if(clone.type==='matching') clone.data.pairs=(clone.data.pairs||[]).map((p:any)=>({...p,id:makeId()}));
  if(clone.type==='ordering') { const items=(clone.data.items||[]).map((x:any)=>({...x,id:makeId()})); clone.data.items=items; clone.data.correctOrderIds=items.map((x:any)=>x.id); }
  return clone;
}
function changeQuestionType(source:Question,type:QuestionType):Question{
  if(source.type===type) return source;
  if((source.type==='single_choice'||source.type==='multiple_choice')&&(type==='single_choice'||type==='multiple_choice')){
    const data=structuredClone(source.data); if(type==='single_choice') data.correctOptionId=source.type==='single_choice'?String(source.data.correctOptionId||''):(Array.isArray(source.data.correctOptionIds)?String(source.data.correctOptionIds[0]||''):''); delete data.correctOptionIds; return {...source,type,data};
  }
  const next=newQuestion(type); return {...next,id:source.id,position:source.position,prompt:source.prompt,points:source.points};
}

function useTheme(){
  const [theme,setTheme]=useState(localStorage.getItem('qf_theme') || 'system');
  useEffect(()=>{
    document.documentElement.dataset.theme = theme === 'system' ? '' : theme;
    localStorage.setItem('qf_theme',theme);
    const colors:Record<string,string>={system:'#0c0f14',midnight:'#080b10',ocean:'#07121a',aurora:'#08100f',paper:'#f4f3ef',contrast:'#000000'};
    document.querySelector('meta[name=theme-color]')?.setAttribute('content',colors[theme]||colors.system);
  },[theme]);
  return [theme,setTheme] as const;
}

function Shell({children}:{children:React.ReactNode}){
  const nav=useNavigate(); const loc=useLocation(); const [theme,setTheme]=useTheme();
  const [menu,setMenu]=useState(false);
  const logged=useTeacher();
  return <div className="app-shell">
    <header className="topbar">
      <Link to="/" className="brand" onClick={()=>setMenu(false)}><span className="brand-mark"><Zap size={17}/></span><span>QuizForge</span><small>CLASSROOM</small></Link>
      <button className="mobile-menu" onClick={()=>setMenu(x=>!x)} aria-label="Открыть меню"><Menu/></button>
      <nav className={menu?'topnav open':'topnav'}>
        {logged ? <><Link className={loc.pathname.startsWith('/teacher')?'active':''} to="/teacher" onClick={()=>setMenu(false)}><LayoutDashboard size={16}/>Панель</Link><Link to="/teacher/tests/new" onClick={()=>setMenu(false)}><Plus size={16}/>Создать</Link><button className="nav-plain" onClick={()=>{api.logout().catch(()=>undefined);localStorage.removeItem('qf_teacher');nav('/teacher/login');setMenu(false)}}><LogOut size={16}/>Выйти</button></> : <Link to="/teacher/login" onClick={()=>setMenu(false)}><LogIn size={16}/>Преподавателю</Link>}
        <ThemeSelect value={theme} onChange={setTheme}/>
      </nav>
    </header>
    <main className="page">{children}</main>
    <footer className="footer"><span>QuizForge Classroom</span><span>Тесты · Realtime · Offline recovery · PWA</span></footer>
  </div>;
}

