function Metric({big,text}:{big:string;text:string}){return <div><b>{big}</b><span>{text}</span></div>}
function Feature({icon,title,text}:{icon:React.ReactNode;title:string;text:string}){return <article className="feature-card"><div className="feature-icon">{icon}</div><h3>{title}</h3><p>{text}</p></article>}

function Setup(){
  const nav=useNavigate(); const [status,setStatus]=useState<any>(null); const [form,setForm]=useState({setupKey:'',username:'',password:'',displayName:''}); const [error,setError]=useState(''); const [loading,setLoading]=useState(false);
  useEffect(()=>{api.setupStatus().then(setStatus).catch(()=>setStatus({needsSetup:false,setupConfigured:false}))},[]);
  if(status && !status.needsSetup) return <Shell><div className="center-card"><div className="eyebrow">SETUP COMPLETE</div><h1>Система уже настроена</h1><p>Первый аккаунт преподавателя создан. Используйте обычный вход.</p><button className="btn primary" onClick={()=>nav('/teacher/login')}>Перейти ко входу</button></div></Shell>;
  const submit=async(e:React.FormEvent)=>{e.preventDefault();setError('');setLoading(true);try{await api.setupTeacher(form);localStorage.setItem('qf_teacher','1');nav('/teacher')}catch(e:any){setError(e.message)}finally{setLoading(false)}};
  return <Shell><div className="auth-layout"><div className="auth-card wide"><div className="eyebrow">FIRST RUN</div><h1>Первоначальная настройка</h1><p>Этот экран доступен только пока в базе нет преподавателей. Ключ берётся из <code>SETUP_KEY</code> на сервере.</p>{!status?.setupConfigured&&<div className="notice danger"><AlertTriangle size={17}/><span>На сервере не задан SETUP_KEY. Добавьте его в переменные окружения и обновите страницу.</span></div>}{error&&<div className="notice danger"><AlertTriangle size={17}/><span>{error}</span></div>}<form className="form-stack" onSubmit={submit}><Field label="Ключ настройки" type="password" value={form.setupKey} onChange={v=>setForm({...form,setupKey:v})}/><Field label="Отображаемое имя" value={form.displayName} onChange={v=>setForm({...form,displayName:v})}/><Field label="Логин" value={form.username} onChange={v=>setForm({...form,username:v.toLowerCase()})}/><Field label="Пароль" type="password" value={form.password} onChange={v=>setForm({...form,password:v})} help="Минимум 10 символов."/><button className="btn primary full" disabled={loading||!status?.setupConfigured}>{loading?'Создаём аккаунт…':'Создать аккаунт преподавателя'}</button></form></div></div></Shell>
}

function TeacherLogin(){
  const nav=useNavigate(); const [username,setUsername]=useState(''); const [password,setPassword]=useState(''); const [error,setError]=useState(''); const [loading,setLoading]=useState(false); const [setup,setSetup]=useState<any>(null);
  useEffect(()=>{api.setupStatus().then(setSetup).catch(()=>undefined)},[]);
  const submit=async(e:React.FormEvent)=>{e.preventDefault();setError('');setLoading(true);try{await api.login(username,password);localStorage.setItem('qf_teacher','1');nav('/teacher')}catch(e:any){setError(e.message)}finally{setLoading(false)}};
  return <Shell><div className="auth-layout"><div className="auth-card"><div className="auth-mark"><ShieldCheck/></div><div className="eyebrow">TEACHER ACCESS</div><h1>Вход в кабинет</h1><p>Управление тестами, банком вопросов, версиями и результатами.</p>{error&&<div className="notice danger"><AlertTriangle size={17}/><span>{error}</span></div>}<form className="form-stack" onSubmit={submit}><Field label="Логин" value={username} onChange={setUsername} autoComplete="username"/><Field label="Пароль" type="password" value={password} onChange={setPassword} autoComplete="current-password"/><button className="btn primary full" disabled={loading}>{loading?'Проверяем…':'Войти'}</button></form>{setup?.needsSetup&&setup?.setupConfigured&&<Link className="setup-link" to="/setup">Первый запуск: создать аккаунт преподавателя</Link>}</div></div></Shell>
}
function Field({label,value,onChange,type='text',placeholder,help,autoComplete}:{label:string;value:string;onChange:(v:string)=>void;type?:string;placeholder?:string;help?:string;autoComplete?:string}){return <label className="field"><span>{label}</span><input type={type} value={value} onChange={e=>onChange(e.target.value)} placeholder={placeholder} autoComplete={autoComplete}/>{help&&<small>{help}</small>}</label>}

function Dashboard(){
  const nav=useNavigate(); const [tests,setTests]=useState<any[]>([]); const [loading,setLoading]=useState(true); const [error,setError]=useState('');
  const load=async()=>{setLoading(true);try{const r=await api.tests();setTests(r)}catch(e:any){if(e.message.includes('Сессия')){localStorage.removeItem('qf_teacher');nav('/teacher/login')}else setError(e.message)}finally{setLoading(false)}};
  useEffect(()=>{load()},[]);
  const create=async()=>{try{const t=await api.createTest({title:'Новый тест',description:'',durationSeconds:600,settings:EMPTY_SETTINGS,questions:[]});nav(`/teacher/tests/${t.id}/edit`)}catch(e:any){setError(e.message)}};
  const totalAttempts=tests.reduce((s,t)=>s+t.attemptCount,0); const active=tests.reduce((s,t)=>s+t.activeCount,0); const warnings=tests.reduce((s,t)=>s+t.warningAttemptCount,0);
  return <Shell><div className="section-head"><div><div className="eyebrow">TEACHER CONSOLE</div><h1>Мои тесты</h1><p>Создавайте, публикуйте и отслеживайте учебные проверки из одной панели.</p></div><div className="head-actions"><button className="btn secondary" onClick={load}><RefreshCw size={16}/>Обновить</button><button className="btn primary" onClick={create}><Plus size={16}/>Новый тест</button></div></div>{error&&<div className="notice danger"><AlertTriangle size={17}/><span>{error}</span></div>}<div className="dashboard-metrics"><Stat label="Тестов" value={tests.length}/><Stat label="Попыток" value={totalAttempts}/><Stat label="Сейчас проходят" value={active}/><Stat label="Сигналы" value={warnings} warning={warnings>0}/></div>{loading?<div className="empty-card"><RefreshCw className="spin"/><span>Загружаем кабинет…</span></div>:<div className="test-list">{tests.map(t=><TestCard key={t.id} t={t} onDuplicate={async()=>{await api.duplicate(t.id);load()}} onPublish={async()=>{await api.publish(t.id,true);load()}} onClose={async()=>{await api.publish(t.id,false);load()}} onDelete={async()=>{if(!window.confirm('Удалить тест? Это действие нельзя отменить.'))return;await api.deleteTest(t.id);load()}}/>)}{!tests.length&&<div className="empty-card"><FilePlus2/><h3>Тестов пока нет</h3><p>Создайте первый тест — конструктор начнётся с чистого листа.</p><button className="btn primary" onClick={create}><Plus size={16}/>Создать тест</button></div>}</div>}</Shell>
}
function Stat({label,value,warning=false}:{label:string;value:any;warning?:boolean}){return <div className={warning?'dash-stat warning':''}><span>{label}</span><b>{value}</b></div>}
function TestCard({t,onDuplicate,onPublish,onClose,onDelete}:{t:any;onDuplicate:()=>Promise<void>;onPublish:()=>Promise<void>;onClose:()=>Promise<void>;onDelete:()=>Promise<void>}){const nav=useNavigate();const [busy,setBusy]=useState(false);const run=async(fn:()=>Promise<void>)=>{setBusy(true);try{await fn()}finally{setBusy(false)}};const hasUnpublished=t.published&&Number(t.currentVersion)!==Number(t.publishedVersion||t.currentVersion);return <article className="test-card"><div className="test-card-head"><div className={t.published?(hasUnpublished?'status':'status live'):'status'}>{t.published&&!hasUnpublished?<span className="dot"/>:null}{t.published?(hasUnpublished?'Есть черновые изменения':'Опубликован'):'Черновик'}</div><span className="version">v{t.currentVersion}</span><button className="icon-btn" title="Редактировать" onClick={()=>nav(`/teacher/tests/${t.id}/edit`)}><Settings2 size={16}/></button></div><h3>{t.title}</h3><p>{t.description||'Без описания'}</p><div className="test-meta"><span><FilePlus2 size={14}/>{t.questionCount} вопросов</span><span><Users size={14}/>{t.attemptCount} попыток</span><span><Clock3 size={14}/>{formatDuration(t.durationSeconds)}</span>{t.activeCount>0&&<span className="meta-live"><span className="dot"/>{t.activeCount} сейчас</span>}{t.published&&<span>Опубликована v{t.publishedVersion||t.currentVersion}</span>}</div>{t.shareCode&&<div className="share-box"><div><span>Код доступа</span><strong>{t.shareCode}</strong></div><button className="icon-btn" onClick={()=>navigator.clipboard?.writeText(`${location.origin}/join/${t.shareCode}`)} title="Скопировать ссылку"><ClipboardCopy size={15}/></button></div>}{t.warningAttemptCount>0&&<div className="test-warning"><AlertTriangle size={14}/><span>{t.warningAttemptCount} попыток требуют проверки технических событий</span></div>}<div className="card-actions"><button className="btn ghost" onClick={()=>nav(`/teacher/tests/${t.id}/results`)}>Результаты</button><button className="btn ghost" disabled={busy} onClick={()=>run(onDuplicate)}><Copy size={14}/>Копия</button>{t.attemptCount===0&&<button className="icon-btn danger-icon" disabled={busy} onClick={()=>run(onDelete)} title="Удалить тест"><Trash2 size={15}/></button>}{hasUnpublished&&<button className="btn secondary" disabled={busy} onClick={()=>run(onPublish)}>Обновить публикацию</button>}{t.published&&<button className="btn ghost" disabled={busy} onClick={()=>run(onClose)}>Закрыть</button>}{!t.published&&<button className="btn primary" disabled={busy} onClick={()=>run(onPublish)}>Опубликовать</button>}</div></article>}

function NewRedirect(){const nav=useNavigate();useEffect(()=>{api.createTest({title:'Новый тест',description:'',durationSeconds:600,settings:EMPTY_SETTINGS,questions:[]}).then(t=>nav(`/teacher/tests/${t.id}/edit`,{replace:true})).catch(()=>nav('/teacher'))},[nav]);return <Shell><div className="empty-card"><RefreshCw className="spin"/><span>Создаём тест…</span></div></Shell>}

function Editor(){
  const {id=''}=useParams(); const nav=useNavigate(); const [test,setTest]=useState<Test|null>(null); const [bank,setBank]=useState<any[]>([]); const [tab,setTab]=useState<'questions'|'settings'>('questions'); const [saving,setSaving]=useState(false); const [dirty,setDirty]=useState(false); const [error,setError]=useState(''); const [importOpen,setImportOpen]=useState(false);
  useEffect(()=>{Promise.all([api.test(id),api.bank()]).then(([t,b])=>{setTest(t);setBank(b)}).catch(e=>setError(e.message))},[id]);
  const update=(patch:Partial<Test>)=>setTest(t=>t?{...t,...patch}:t);
  const save=async()=>{if(!test)return;setSaving(true);setError('');try{const saved=await api.updateTest(id,test);setTest(saved);setDirty(false)}catch(e:any){setError(e.message)}finally{setSaving(false)}};
  const add=(type:QuestionType)=>{if(!test)return;update({questions:[...test.questions,{...newQuestion(type),position:test.questions.length}]});setDirty(true);};
  const changeQuestion=(index:number,q:Question)=>{if(!test)return;const questions=[...test.questions];questions[index]=q;update({questions});setDirty(true)};
  const removeQuestion=(index:number)=>{if(!test)return;update({questions:test.questions.filter((_,i)=>i!==index).map((q,i)=>({...q,position:i}))});setDirty(true)};
  const moveQuestion=(index:number,delta:number)=>{if(!test)return;const target=index+delta;if(target<0||target>=test.questions.length)return;const q=[...test.questions];[q[index],q[target]]=[q[target],q[index]];update({questions:q.map((x,i)=>({...x,position:i}))});setDirty(true)};
  const duplicateQuestion=(index:number)=>{if(!test)return;const clone=duplicateQuestionModel(test.questions[index],index+1);const q=[...test.questions.slice(0,index+1),clone,...test.questions.slice(index+1)].map((x,i)=>({...x,position:i}));update({questions:q});setDirty(true)};
  const importSelected=async(ids:string[])=>{try{const updated=await api.importQuestions(id,ids);setTest(updated);setDirty(false);setImportOpen(false)}catch(e:any){setError(e.message)}};
  if(!test)return <Shell><div className="empty-card"><RefreshCw className="spin"/><span>{error||'Загрузка редактора…'}</span></div></Shell>;
  const total=test.questions.reduce((s,q)=>s+q.points,0);
  return <Shell><div className="editor-head"><div className="editor-title"><button className="back-link" onClick={()=>nav('/teacher')}><ArrowLeft size={16}/>Назад</button><input className="title-input" value={test.title} onChange={e=>{update({title:e.target.value});setDirty(true)}} aria-label="Название теста"/><textarea className="description-input" value={test.description} onChange={e=>{update({description:e.target.value});setDirty(true)}} placeholder="Описание для учащихся…"/><div className="save-state">{dirty?<span className="unsaved">● Есть несохранённые изменения</span>:<span className="saved"><CheckCircle2 size={14}/> Сохранено · версия {test.currentVersion}</span>}</div></div><div className="editor-actions"><button className="btn ghost" onClick={()=>nav(`/teacher/tests/${id}/results`)}>Результаты</button><button className="btn secondary" onClick={()=>setImportOpen(true)}><Download size={15}/>Из банка</button><button className="btn primary" disabled={!dirty||saving} onClick={save}>{saving?<RefreshCw className="spin" size={15}/>:<Save size={15}/>} {saving?'Сохраняем…':'Сохранить'}</button></div></div>{error&&<div className="notice danger"><AlertTriangle size={17}/><span>{error}</span></div>}<div className="editor-tabs"><button className={tab==='questions'?'active':''} onClick={()=>setTab('questions')}>Вопросы <b>{test.questions.length}</b></button><button className={tab==='settings'?'active':''} onClick={()=>setTab('settings')}>Настройки теста</button><div className="editor-summary"><span>{total} баллов</span><span>{formatDuration(test.durationSeconds)}</span>{test.published&&<span className={Number(test.currentVersion)!==Number(test.publishedVersion||test.currentVersion)?'status':'status live'}>{Number(test.currentVersion)!==Number(test.publishedVersion||test.currentVersion)?`Черновик v${test.currentVersion} · опубликована v${test.publishedVersion}`:`Опубликован · v${test.publishedVersion||test.currentVersion}`}{test.shareCode?` · ${test.shareCode}`:''}</span>}</div></div>{tab==='questions'?<><div className="add-question-bar"><div><b>Добавить задание</b><span>Выберите тип — его можно менять позже.</span></div><div className="type-buttons">{Object.entries(TYPE_META).map(([type,m])=><button key={type} className="type-button" onClick={()=>add(type as QuestionType)}><span>{m.icon}</span>{m.label}</button>)}</div></div><div className="question-list">{test.questions.map((q,i)=><QuestionEditor key={q.id||i} q={q} index={i} onChange={q=>changeQuestion(i,q)} onRemove={()=>removeQuestion(i)} onMove={(d)=>moveQuestion(i,d)} onDuplicate={()=>duplicateQuestion(i)}/>)}{!test.questions.length&&<div className="empty-card compact"><FilePlus2/><h3>Пустой тест</h3><p>Добавьте первый вопрос сверху. Начните с чистого листа.</p></div>}</div></>:<TestSettingsEditor test={test} onChange={(patch)=>{update({settings:{...test.settings,...patch}});setDirty(true)}} onDurationChange={(minutes)=>{update({durationSeconds:Math.max(0,Math.min(86400,Math.round(minutes*60)))});setDirty(true)}}/>}<div className="editor-bottom"><span>{dirty?'Изменения не отправлены на сервер.':'Все изменения сохранены.'}</span><button className="btn primary" disabled={!dirty||saving} onClick={save}><Save size={15}/>Сохранить изменения</button></div>{importOpen&&<QuestionBankModal bank={bank} onClose={()=>setImportOpen(false)} onImport={importSelected}/>}</Shell>
}

function QuestionEditor({q,index,onChange,onRemove,onMove,onDuplicate}:{q:Question;index:number;onChange:(q:Question)=>void;onRemove:()=>void;onMove:(d:number)=>void;onDuplicate:()=>void}){
  const setData=(patch:any)=>onChange({...q,data:{...q.data,...patch}});
  return <article className="question-card"><div className="q-card-top"><div className="q-type"><span className="q-badge">{String(index+1).padStart(2,'0')}</span><select className="type-select" value={q.type} onChange={e=>onChange(changeQuestionType(q,e.target.value as QuestionType))}>{Object.entries(TYPE_META).map(([type,m])=><option key={type} value={type}>{m.label}</option>)}</select></div><div className="q-tools"><label className="points"><span>баллы</span><input type="number" min="0" step="0.5" value={q.points} onChange={e=>onChange({...q,points:Number(e.target.value)})}/></label><button className="icon-btn" title="Вверх" onClick={()=>onMove(-1)}><ArrowUp size={15}/></button><button className="icon-btn" title="Вниз" onClick={()=>onMove(1)}><ArrowDown size={15}/></button><button className="icon-btn" title="Дублировать" onClick={onDuplicate}><Copy size={15}/></button><button className="icon-btn danger-icon" title="Удалить" onClick={onRemove}><Trash2 size={15}/></button></div></div><textarea className="question-prompt" value={q.prompt} onChange={e=>onChange({...q,prompt:e.target.value})}/><QuestionConfig q={q} setData={setData} onChange={onChange}/></article>
}
function QuestionConfig({q,setData,onChange}:{q:Question;setData:(d:any)=>void;onChange:(q:Question)=>void}){
  if(q.type==='single_choice'||q.type==='multiple_choice'){
    const opts=q.data.options||[]; const selected=q.type==='single_choice'?[q.data.correctOptionId]:q.data.correctOptionIds||[];
    return <div className="config-stack"><div className="config-help">{TYPE_META[q.type].hint}</div>{opts.map((o:any,i:number)=><div className="option-edit" key={o.id}><button className={selected.includes(o.id)?'correct-toggle on':'correct-toggle'} onClick={()=>q.type==='single_choice'?setData({correctOptionId:o.id}):setData({correctOptionIds:selected.includes(o.id)?selected.filter((x:string)=>x!==o.id):[...selected,o.id]})} title="Пометить правильным">{selected.includes(o.id)?<Check size={14}/>:<span/>}</button><input value={o.text} onChange={e=>{const next=[...opts];next[i]={...o,text:e.target.value};setData({options:next})}}/><button className="icon-btn" onClick={()=>setData({options:opts.filter((_:any,j:number)=>j!==i),...(q.type==='single_choice'&&q.data.correctOptionId===o.id?{correctOptionId:''}:{}),...(q.type==='multiple_choice'?{correctOptionIds:selected.filter((x:string)=>x!==o.id)}:{})})}><X size={15}/></button></div>)}<button className="text-action" onClick={()=>setData({options:[...opts,{id:makeId(),text:`Вариант ${opts.length+1}`}]})}><Plus size={14}/>Добавить вариант</button></div>
  }
  if(q.type==='true_false') return <div className="config-stack"><div className="config-help">{TYPE_META[q.type].hint}</div><div className="segmented"><button className={q.data.correct===true?'selected':''} onClick={()=>setData({correct:true})}>Верно</button><button className={q.data.correct===false?'selected':''} onClick={()=>setData({correct:false})}>Неверно</button></div></div>;
  if(q.type==='fill_blank') return <div className="config-stack"><div className="config-help">Укажите допустимые ответы. Один ответ на строку.</div><textarea value={(q.data.accepted||[]).join('\n')} onChange={e=>setData({accepted:e.target.value.split(/\n/).map((x:string)=>x.trim()).filter(Boolean)})} placeholder={'Length\nlength'}/></div>;
  if(q.type==='matching'){const pairs=q.data.pairs||[];return <div className="config-stack"><div className="config-help">Студент увидит все правые элементы как варианты выбора.</div>{pairs.map((p:any,i:number)=><div className="pair-edit" key={p.id}><input value={p.left} placeholder="Левый элемент" onChange={e=>{const next=[...pairs];next[i]={...p,left:e.target.value};setData({pairs:next})}}/><span>↔</span><input value={p.right} placeholder="Правый элемент" onChange={e=>{const next=[...pairs];next[i]={...p,right:e.target.value};setData({pairs:next})}}/><button className="icon-btn" onClick={()=>setData({pairs:pairs.filter((_:any,j:number)=>j!==i)})}><X size={15}/></button></div>)}<button className="text-action" onClick={()=>setData({pairs:[...pairs,{id:makeId(),left:'Новый элемент',right:'Новое определение'}]})}><Plus size={14}/>Добавить пару</button></div>}
  if(q.type==='ordering'){const items=q.data.items||[];return <div className="config-stack"><div className="config-help">Порядок, в котором элементы сейчас расположены, считается правильным.</div>{items.map((item:any,i:number)=><div className="order-edit" key={item.id}><GripVertical size={15}/><input value={item.text} onChange={e=>{const next=[...items];next[i]={...item,text:e.target.value};setData({items:next,correctOrderIds:next.map((x:any)=>x.id)})}}/><button className="icon-btn" disabled={i===0} onClick={()=>{const next=[...items];[next[i-1],next[i]]=[next[i],next[i-1]];setData({items:next,correctOrderIds:next.map((x:any)=>x.id)})}}><ArrowUp size={14}/></button><button className="icon-btn" disabled={i===items.length-1} onClick={()=>{const next=[...items];[next[i+1],next[i]]=[next[i],next[i+1]];setData({items:next,correctOrderIds:next.map((x:any)=>x.id)})}}><ArrowDown size={14}/></button><button className="icon-btn" onClick={()=>{const next=items.filter((_:any,j:number)=>j!==i);setData({items:next,correctOrderIds:next.map((x:any)=>x.id)})}}><X size={14}/></button></div>)}<button className="text-action" onClick={()=>{const next=[...items,{id:makeId(),text:`Элемент ${items.length+1}`}];setData({items:next,correctOrderIds:next.map((x:any)=>x.id)})}}><Plus size={14}/>Добавить элемент</button></div>}
  if(q.type==='numeric') return <div className="two-fields"><Field label="Правильное число" value={String(q.data.correct??'')} onChange={v=>setData({correct:Number(v)})}/><Field label="Допуск" value={String(q.data.tolerance??0)} onChange={v=>setData({tolerance:Number(v)})} help="Например 0.01"/></div>;
  return <div className="config-stack"><div className="config-help">{TYPE_META[q.type].hint}</div><label className="field"><span>Инструкция / критерии проверки</span><textarea value={q.data.rubric||''} onChange={e=>setData({rubric:e.target.value})} placeholder="Что должен содержать правильный ответ?"/></label></div>
}

function TestSettingsEditor({test,onChange,onDurationChange}:{test:Test;onChange:(patch:Partial<TestSettings>)=>void;onDurationChange:(minutes:number)=>void}){const s=test.settings;return <div className="settings-layout"><div className="settings-main"><section className="settings-card"><div className="eyebrow">SESSION</div><h2>Проведение</h2><div className="settings-grid"><label className="field"><span>Время на тест</span><div className="inline-input"><input type="number" min="0" max="1440" value={Math.round(test.durationSeconds/60)} onChange={e=>onDurationChange(Number(e.target.value))}/><b>мин</b></div><small>0 = без ограничения времени.</small></label></div><Toggle label="Случайный порядок вопросов" value={s.randomizeQuestions} onChange={v=>onChange({randomizeQuestions:v})}/><Toggle label="Перемешивать варианты ответов" value={s.randomizeOptions} onChange={v=>onChange({randomizeOptions:v})}/><Toggle label="Разрешить восстановление попытки" value={s.allowResume} onChange={v=>onChange({allowResume:v})}/><Toggle label="Разрешить отправку после истечения времени" value={s.allowLateSubmit} onChange={v=>onChange({allowLateSubmit:v})}/></section></div><aside className="settings-side"><section className="settings-card"><div className="eyebrow">RESULTS</div><h2>Результаты</h2><Toggle label="Показывать баллы ученику" value={s.showScoreOnSubmit} onChange={v=>onChange({showScoreOnSubmit:v})}/><Toggle label="Имя / ник обязателен" value={s.requireStudentName} onChange={v=>onChange({requireStudentName:v})}/><Toggle label="Отслеживать тех. события" value={s.trackFocusEvents} onChange={v=>onChange({trackFocusEvents:v})}/><label className="field"><span>Порог прохождения</span><input type="number" min="0" max="100" value={s.passPercent} onChange={e=>onChange({passPercent:Number(e.target.value)})}/><small>Информационный порог для статистики.</small></label></section></aside></div>}
function Toggle({label,value,onChange}:{label:string;value:boolean;onChange:(v:boolean)=>void}){return <button className="toggle-row" onClick={()=>onChange(!value)}><span>{label}</span><span className={value?'switch on':'switch'}><i/></span></button>}

function QuestionBankModal({bank,onClose,onImport}:{bank:any[];onClose:()=>void;onImport:(ids:string[])=>Promise<void>}){const [search,setSearch]=useState('');const [selected,setSelected]=useState<string[]>([]);const filtered=bank.filter(q=>`${q.testTitle} ${q.prompt}`.toLowerCase().includes(search.toLowerCase()));return <div className="modal-backdrop"><div className="modal-panel"><div className="modal-head"><div><div className="eyebrow">QUESTION BANK</div><h2>Добавить вопросы</h2><p>Выберите задания из уже созданных тестов и добавьте их копиями в текущую версию.</p></div><button className="icon-btn" onClick={onClose}><X/></button></div><label className="search-box"><Search size={16}/><input value={search} onChange={e=>setSearch(e.target.value)} placeholder="Поиск по тестам и вопросам…"/></label><div className="bank-list">{filtered.map(q=><label className="bank-row" key={q.id}><input type="checkbox" checked={selected.includes(q.id)} onChange={()=>setSelected(x=>x.includes(q.id)?x.filter(id=>id!==q.id):[...x,q.id])}/><div><b>{q.prompt}</b><span>{q.testTitle} · {TYPE_META[q.type as QuestionType]?.label || q.type} · {q.points} б.</span></div></label>)}{!filtered.length&&<div className="empty-card compact">Ничего не найдено.</div>}</div><div className="modal-actions"><span>{selected.length} выбрано</span><div><button className="btn secondary" onClick={onClose}>Отмена</button><button className="btn primary" disabled={!selected.length} onClick={()=>onImport(selected)}>Добавить</button></div></div></div></div>}

function Results(){
  const {id=''}=useParams(); const nav=useNavigate(); const [test,setTest]=useState<any>(null); const [rows,setRows]=useState<any[]>([]); const [selected,setSelected]=useState<any>(null); const [detail,setDetail]=useState<any>(null); const [events,setEvents]=useState<any[]>([]); const [error,setError]=useState('');
  const load=async()=>{try{const [t,r]=await Promise.all([api.test(id),api.results(id)]);setTest(t);setRows(r)}catch(e:any){setError(e.message)}};
  useEffect(()=>{load();const timer=setInterval(load,2500);return()=>clearInterval(timer)},[id]);
  const open=async(r:any)=>{setSelected(r);try{const [d,e]=await Promise.all([api.detail(r.id),api.events(r.id)]);setDetail(d);setEvents(e)}catch(e:any){setError(e.message)}};
  const summary=useMemo(()=>{const finalized=rows.filter(r=>r.status==='submitted'||r.status==='expired');const submitted=finalized.length;const scores=finalized.filter(r=>r.score!=null&&r.maxScore!=null);const avg=scores.length?scores.reduce((s,r)=>s+(Number(r.score||0)/Math.max(1,Number(r.maxScore||1))*100),0)/scores.length:0;const max=rows.find(r=>r.maxScore!=null)?.maxScore||0;const passPercent=Number(test?.settings?.passPercent??60);const passed=finalized.filter(r=>r.score!=null&&r.maxScore>0&&(Number(r.score)/Number(r.maxScore)*100)>=passPercent).length;return {submitted,avg,max,warnings:rows.filter(r=>r.warningCount>0).length,pending:finalized.filter(r=>r.reviewStatus!=='reviewed').length,passed,passPercent}},[rows,test]);
  const exportCsv=()=>{const passPercent=Number(test?.settings?.passPercent??60);const lines=[['Учащийся','Статус','Баллы','Максимум','Процент','Порог','Сигналы','Начало','Отправлено'].join(';'),...rows.map(r=>{const pct=r.score!=null&&r.maxScore?Number(r.score)/Number(r.maxScore)*100:null;return[csv(r.studentName),csv(r.status),r.score??'',r.maxScore??'',pct==null?'':pct.toFixed(1),passPercent,r.warningCount,csv(r.startedAt),csv(r.submittedAt)].join(';')})];const blob=new Blob(['\ufeff'+lines.join('\n')],{type:'text/csv;charset=utf-8'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`quizforge-${id}.csv`;a.click();URL.revokeObjectURL(a.href)};
  const finalize=async()=>{if(!selected)return;await api.review(selected.id);setSelected({...selected,reviewStatus:'reviewed'});setRows(x=>x.map(r=>r.id===selected.id?{...r,reviewStatus:'reviewed'}:r))};
  return <Shell><div className="section-head"><div><button className="back-link" onClick={()=>nav('/teacher')}><ArrowLeft size={16}/>Назад</button><div className="eyebrow">LIVE RESULTS</div><h1>{test?.title||'Результаты'}</h1><p>{rows.length} попыток · обновление каждые 2,5 секунды</p></div><div className="head-actions"><button className="btn secondary" onClick={exportCsv}><Download size={15}/>CSV</button><button className="btn ghost" onClick={load}><RefreshCw size={15}/>Обновить</button></div></div>{error&&<div className="notice danger"><AlertTriangle size={17}/><span>{error}</span></div>}{summary.warnings>0&&<div className="notice warning"><AlertTriangle size={17}/><div><b>Перед фиксацией результатов есть технические сигналы.</b><span>Проверьте события попыток. Сигнал не является автоматическим выводом о нарушении.</span></div></div>}<div className="dashboard-metrics"><Stat label="Участников" value={rows.length}/><Stat label="Завершили" value={summary.submitted}/><Stat label="Средний результат" value={rows.length?`${summary.avg.toFixed(0)}%`:'—'}/><Stat label="Прошли порог" value={`${summary.passed}/${rows.length}`}/></div><div className="results-table panel"><div className="table-head"><span>Учащийся</span><span>Статус</span><span>Баллы</span><span>Сигналы</span><span>Активность</span></div>{rows.map(r=><button className="result-row" key={r.id} onClick={()=>open(r)}><span className="student-name"><span className="avatar">{(r.studentName||'Б').slice(0,1).toUpperCase()}</span><span><b>{r.studentName}</b><small>{r.reviewStatus==='reviewed'?'Проверено':'Требует внимания'}</small></span></span><span><span className={r.status==='submitted'?'status live':'status'}>{r.status==='submitted'?'Завершено':r.status==='expired'?'Истекло':'В процессе'}</span></span><span className="score">{r.score==null?'—':`${r.score} / ${r.maxScore}`}</span><span>{r.warningCount>0?<span className="warning-count"><AlertTriangle size={14}/>{r.warningCount}</span>:<span className="muted">0</span>}</span><span className="muted">{dateShort(r.lastSeenAt)}</span></button>)}{!rows.length&&<div className="empty-card compact">Пока нет попыток.</div>}</div>{selected&&<AttemptDrawer selected={selected} detail={detail} events={events} onClose={()=>{setSelected(null);setDetail(null)}} onFinalized={finalize}/>}</Shell>
}
function AttemptDrawer({selected,detail,events,onClose,onFinalized}:{selected:any;detail:any;events:any[];onClose:()=>void;onFinalized:()=>Promise<void>}){const [grading,setGrading]=useState<Record<string,string>>({});const [feedback,setFeedback]=useState<Record<string,string>>({});const [saving,setSaving]=useState<string>('');const answerMap=useMemo(()=>new Map((detail?.answers||[]).map((a:any)=>[a.questionId,a])),[detail]);return <div className="modal-backdrop" onClick={onClose}><aside className="drawer" onClick={e=>e.stopPropagation()}><div className="drawer-head"><div><div className="eyebrow">ATTEMPT</div><h2>{selected.studentName}</h2><span className="muted">{selected.status==='submitted'?'Завершено':'В процессе'} · {selected.score??'—'} / {selected.maxScore??'—'}</span></div><button className="icon-btn" onClick={onClose}><X/></button></div><div className="drawer-grid"><div><span>Сигналы</span><b className={selected.warningCount?'warning-text':''}>{selected.warningCount}</b></div><div><span>Версия</span><b>зафиксирована</b></div><div><span>Активность</span><b>{dateShort(selected.lastSeenAt)}</b></div></div><section><h3>Ответы</h3><div className="answer-review-list">{(detail?.questions||[]).map((q:any,i:number)=>{const a=answerMap.get(q.id);const manual=['short_text','long_text','code'].includes(q.type);return <div className="review-question" key={q.id||i}><div className="review-q-head"><span>{i+1}. {q.prompt}</span><b>{manual?(a?.reviewStatus==='reviewed'?`${a.points??0} / ${q.points}`:'Ручная проверка'):`${a?.points??0} / ${q.points}`}</b></div>{manual&&a&&<><pre className="answer-code">{typeof a.answer==='string'?a.answer:JSON.stringify(a.answer,null,2)}</pre>{a.feedback&&<div className="feedback-read"><b>Комментарий</b><span>{a.feedback}</span></div>}<div className="manual-controls"><input type="number" min="0" max={q.points} value={grading[q.id]??String(a.points??'')} onChange={e=>setGrading(x=>({...x,[q.id]:e.target.value}))} placeholder={`0–${q.points}`}/><input value={feedback[q.id]??a.feedback??''} onChange={e=>setFeedback(x=>({...x,[q.id]:e.target.value}))} placeholder="Комментарий учащемуся (необязательно)"/><button className="btn primary small" disabled={saving===q.id} onClick={async()=>{setSaving(q.id);try{const r=await api.manualGrade(selected.id,q.id,Number(grading[q.id]??0),feedback[q.id]??a.feedback??'');setDetail((d:any)=>({...d,answers:d.answers.map((x:any)=>x.questionId===q.id?{...x,points:Number(grading[q.id]??0),reviewStatus:'reviewed',feedback:feedback[q.id]??a.feedback??''}:x)}));setSelected((s:any)=>({...s,score:r.score,reviewStatus:r.reviewStatus}))}catch(e:any){alert(e.message)}finally{setSaving('')}}}>{saving===q.id?'…':'Оценить'}</button></div></>}</div>})}{!detail&&<div className="empty-card compact"><RefreshCw className="spin"/>Загрузка деталей…</div>}</div></section><section><h3>Журнал технических событий</h3><div className="event-list">{events.map(e=><div className={['offline','pagehide','tab_hidden','heartbeat_timeout','auto_submit_pending'].includes(e.type)?'event warn':'event'} key={e.id}><span>{eventLabel(e.type)}</span><small>{dateShort(e.createdAt)}</small></div>)}{!events.length&&<div className="muted">Событий нет.</div>}</div><div className="drawer-note"><ShieldCheck size={16}/><span>Сигналы предназначены для проверки контекста. Система не объявляет нарушение автоматически.</span></div></section><div className="drawer-actions"><button className="btn secondary" onClick={onClose}>Закрыть</button><button className="btn primary" disabled={selected.reviewStatus==='reviewed'} onClick={onFinalized}><CheckCircle2 size={15}/>Отметить проверенным</button></div></aside></div>}

function Join(){
  const {code:routeCode}=useParams();const [search]=useSearchParams();const [code,setCode]=useState((routeCode||search.get('code')||'').toUpperCase());const [name,setName]=useState('');const [error,setError]=useState('');const [loading,setLoading]=useState(false);const [resumeAvailable,setResumeAvailable]=useState(false);const nav=useNavigate();
  const recent=useMemo(()=>{try{return JSON.parse(localStorage.getItem('qf_recent_attempts')||'[]')}catch{return[]}},[]);
  const same=recent.find((x:any)=>x.code===code);
  useEffect(()=>{let cancelled=false;if(!same)return setResumeAvailable(false);api.attempt(same.id,same.token).then((r:any)=>{if(!cancelled)setResumeAvailable(r.attempt.status==='active'&&r.test?.settings?.allowResume!==false)}).catch(()=>{if(!cancelled){setResumeAvailable(false);localStorage.setItem('qf_recent_attempts',JSON.stringify(recent.filter((x:any)=>x.id!==same.id)))}});return()=>{cancelled=true}},[code]);
  const resume=async(item:any)=>{try{const r=await api.attempt(item.id,item.token);if(r.attempt.status==='active'&&r.test?.settings?.allowResume!==false)nav(`/attempt/${item.id}`);else setResumeAvailable(false)}catch{setResumeAvailable(false)}};
  const submit=async(e:React.FormEvent)=>{e.preventDefault();setError('');setLoading(true);try{const r=await api.join(code,name);localStorage.setItem(`qf_attempt_${r.attemptId}`,JSON.stringify({token:r.accessToken,code,startedAt:r.startedAt}));const list=[{id:r.attemptId,token:r.accessToken,code,startedAt:r.startedAt},...recent.filter((x:any)=>x.code!==code)].slice(0,5);localStorage.setItem('qf_recent_attempts',JSON.stringify(list));nav(`/attempt/${r.attemptId}`)}catch(e:any){setError(e.message)}finally{setLoading(false)}};
  return <Shell><div className="join-layout"><div className="join-card"><div className="eyebrow">STUDENT ACCESS</div><h1>Пройти тест</h1><p>Регистрация не нужна. Введите код, затем при необходимости укажите имя или ник.</p>{error&&<div className="notice danger"><AlertTriangle size={17}/><span>{error}</span></div>}<form className="form-stack" onSubmit={submit}><label className="field code-field"><span>Код теста</span><input value={code} onChange={e=>setCode(e.target.value.toUpperCase())} placeholder="QF-ABC123" inputMode="text" autoCapitalize="characters"/><small>Код обычно выглядит как QF-XXXXXX.</small></label><Field label="Имя или ник" value={name} onChange={setName} placeholder="Можно оставить пустым"/><button className="btn primary full" disabled={loading||code.trim().length<4}>{loading?'Подключаемся…':'Начать тест'}</button></form>{same&&resumeAvailable&&<div className="resume-card"><div><b>Есть незавершённая попытка</b><span>{same.code} · можно продолжить с этого устройства.</span></div><button className="btn secondary" onClick={()=>resume(same)}>Продолжить</button></div>}</div><div className="join-aside"><div className="join-feature"><CheckCircle2/><div><b>Без регистрации</b><span>Ученик не создаёт аккаунт.</span></div></div><div className="join-feature"><RefreshCw/><div><b>Ответы не теряются</b><span>Есть локальный draft и серверная синхронизация.</span></div></div><div className="join-feature"><ShieldCheck/><div><b>Версия фиксируется</b><span>Изменения теста после старта не меняют попытку.</span></div></div></div></div></Shell>
}

function StudentAttempt(){
  const {id=''}=useParams();const nav=useNavigate();const [data,setData]=useState<any>(null);const [answers,setAnswers]=useState<Record<string,any>>({});const [connection,setConnection]=useState(navigator.onLine);const [saving,setSaving]=useState<Record<string,boolean>>({});const [submitted,setSubmitted]=useState<any>(null);const [error,setError]=useState('');const [remaining,setRemaining]=useState(0);const [token,setToken]=useState('');
  useEffect(()=>{try{const raw=localStorage.getItem(`qf_attempt_${id}`);if(!raw){setError('Ключ попытки не найден на этом устройстве. Вернитесь к странице подключения.');return;}const parsed=JSON.parse(raw);setToken(parsed.token);api.attempt(id,parsed.token).then(r=>{setData(r);const merged:any={};for(const a of r.answers||[])merged[a.questionId]=a.answer;try{const local=JSON.parse(localStorage.getItem(`qf_draft_${id}`)||'{}');Object.assign(merged,local)}catch{}setAnswers(merged)}).catch(e=>setError(e.message))}catch{setError('Не удалось восстановить попытку.')}},[id]);
  useEffect(()=>{if(!data)return;const tick=()=>{const total=data.test.durationSeconds*1000;if(!total){setRemaining(0);return}const left=Math.max(0,Math.ceil((new Date(data.attempt.startedAt).getTime()+total-Date.now())/1000));setRemaining(left)};tick();const timer=setInterval(tick,1000);return()=>clearInterval(timer)},[data]);
  useEffect(()=>{if(!data||submitted||data.test.durationSeconds<=0||remaining!==0)return;submit(true)},[remaining,data,submitted]);
  useEffect(()=>{
    if(!data)return;
    const heartbeat=()=>api.heartbeat(id,token).then(r=>{setConnection(true);if(r.status==='expired'){setSubmitted({status:'expired',score:r.score,maxScore:r.maxScore,pendingManual:r.pendingManual,showScore:data.test.settings.showScoreOnSubmit});setData((d:any)=>({...d,attempt:{...d.attempt,status:'expired',score:r.score,maxScore:r.maxScore}}));}}).catch(()=>setConnection(false));
    const timer=setInterval(heartbeat,8000);heartbeat();
    const offline=()=>{setConnection(false);api.event(id,token,'offline',{online:false}).catch(()=>undefined)};
    const online=()=>{setConnection(true);api.event(id,token,'online',{online:true}).catch(()=>undefined);flushQueue();};
    const hidden=()=>{if(document.visibilityState==='hidden' && data.test.settings.trackFocusEvents)api.event(id,token,'tab_hidden',{visibilityState:document.visibilityState}).catch(()=>undefined)};
    const pagehide=()=>{if(data.test.settings.trackFocusEvents)navigator.sendBeacon?.(`/api/attempts/${id}/events`,new Blob([JSON.stringify({type:'pagehide',payload:{reason:'pagehide'},accessToken:token})],{type:'application/json'}));};
    window.addEventListener('offline',offline);window.addEventListener('online',online);document.addEventListener('visibilitychange',hidden);window.addEventListener('pagehide',pagehide);
    return()=>{clearInterval(timer);window.removeEventListener('offline',offline);window.removeEventListener('online',online);document.removeEventListener('visibilitychange',hidden);window.removeEventListener('pagehide',pagehide)};
  },[data,id,token]);
  const flushQueue=()=>{const raw=localStorage.getItem(`qf_queue_${id}`);if(!raw)return;let queue:any[]=[];try{queue=JSON.parse(raw)}catch{return}if(!queue.length)return;Promise.allSettled(queue.map(item=>api.answer(id,token,item.questionId,item.answer,item.clientUpdatedAt))).then(results=>{const remaining=queue.filter((_:any,i:number)=>results[i].status==='rejected');if(remaining.length)localStorage.setItem(`qf_queue_${id}`,JSON.stringify(remaining));else localStorage.removeItem(`qf_queue_${id}`);setConnection(remaining.length===0)})};
  const answer=(q:Question,v:any)=>{if(submitted)return;const next={...answers,[q.id!]:v};const clientUpdatedAt=Date.now();setAnswers(next);try{localStorage.setItem(`qf_draft_${id}`,JSON.stringify(next))}catch{};setSaving(s=>({...s,[q.id!]:true}));api.answer(id,token,q.id!,v,clientUpdatedAt).then(()=>{setSaving(s=>({...s,[q.id!]:false}));let queue:any[]=[];try{queue=JSON.parse(localStorage.getItem(`qf_queue_${id}`)||'[]')}catch{};queue=queue.filter(x=>x.questionId!==q.id);if(queue.length)localStorage.setItem(`qf_queue_${id}`,JSON.stringify(queue));else localStorage.removeItem(`qf_queue_${id}`)}).catch(()=>{setConnection(false);setSaving(s=>({...s,[q.id!]:false}));let queue:any[]=[];try{queue=JSON.parse(localStorage.getItem(`qf_queue_${id}`)||'[]')}catch{};queue=[...queue.filter(x=>x.questionId!==q.id),{questionId:q.id,answer:v,clientUpdatedAt}];localStorage.setItem(`qf_queue_${id}`,JSON.stringify(queue))})};
  const submit=async(auto=false)=>{if(submitted)return;flushQueue();if(!connection&&auto){try{await api.event(id,token,'auto_submit_pending',{})}catch{}return}try{const r=await api.submit(id,token);setSubmitted(r);setData((d:any)=>({...d,attempt:{...d.attempt,status:r.status,score:r.score,submittedAt:new Date().toISOString()}}))}catch(e:any){if(auto){try{await api.event(id,token,'auto_submit_pending',{message:e.message})}catch{}setError('Время истекло. Ожидаем восстановление связи для отправки результата.')}else setError(e.message)}};
  if(error&&!data)return <Shell><div className="center-card"><AlertTriangle className="danger-big"/><h1>Не удалось открыть попытку</h1><p>{error}</p><button className="btn secondary" onClick={()=>nav('/join')}>Вернуться к коду</button></div></Shell>;
  if(!data)return <Shell><div className="empty-card"><RefreshCw className="spin"/><span>Восстанавливаем попытку…</span></div></Shell>;
  if(submitted)return <Shell><div className="result-screen"><div className="result-icon"><CheckCircle2/></div><div className="eyebrow">SUBMITTED</div><h1>Тест отправлен</h1>{submitted.showScore===false?<p>Ответы сохранены. Результат будет доступен после проверки преподавателем.</p>:submitted.pendingManual?<p>Автоматическая часть проверена. Есть задания с ручной проверкой.</p>:<p>Результат: <strong>{submitted.score}</strong> из <strong>{submitted.maxScore}</strong> баллов.</p>}<div className="result-actions"><Link className="btn primary" to="/join">Готово</Link></div></div></Shell>;
  const filled=Object.keys(answers).filter(k=>answers[k]!==''&&answers[k]!==null&&answers[k]!==undefined).length;const percent=data.test.questions.length?Math.round(filled/data.test.questions.length*100):0;
  return <Shell><div className="attempt-shell"><aside className="attempt-sidebar"><div className="attempt-brand">{data.test.title}</div><div className="student-chip"><UserRound size={13}/>{data.attempt.studentName}</div><div className={remaining<60?'timer danger':'timer'}><Clock3 size={16}/><b>{remaining?formatClock(remaining):'Без лимита'}</b><span>{connection?'Синхронизировано':'Офлайн · ответы в очереди'}</span></div><div className="progress-card"><span>Заполнено</span><b>{percent}%</b><div className="progress-track"><i style={{width:`${percent}%`}}/></div><small>{filled} из {data.test.questions.length}</small></div><div className="sidebar-note"><ShieldCheck size={15}/><span>Прерывания и технические события записываются в журнал преподавателя.</span></div></aside><main className="attempt-main"><div className="attempt-head"><div><div className="live-line"><span className="status live"><span className="dot"/> LIVE</span><span>{data.test.questions.length} вопросов</span></div><h1>{data.test.title}</h1><p>{data.test.description}</p></div><div className={connection?'sync-badge':'sync-badge bad'}>{connection?<Check size={14}/>:<AlertTriangle size={14}/>} {connection?'соединение активно':'нет соединения'}</div></div>{data.test.settings.trackFocusEvents&&<div className="notice warning"><ShieldCheck size={16}/><span>Скрытие вкладки, потеря сети и уход со страницы фиксируются как технические события. Это не автоматический вывод о нарушении.</span></div>}<div className="student-question-list">{data.test.questions.map((q:Question,i:number)=><StudentQuestion key={q.id||i} q={q} index={i} value={answers[q.id!]} saving={!!saving[q.id!]} onChange={v=>answer(q,v)}/>)}</div><button className="btn primary submit-btn" onClick={()=>submit(false)}><CheckCircle2 size={17}/>Завершить тест</button>{error&&<div className="notice danger"><AlertTriangle size={17}/><span>{error}</span></div>}</main></div></Shell>
}

function StudentQuestion({q,index,value,saving,onChange}:{q:Question;index:number;value:any;saving:boolean;onChange:(v:any)=>void}){const opts=q.data.options||[];const isSelected=(x:any)=>Array.isArray(value)&&value.includes(x);return <article className="student-question"><div className="student-q-top"><span className="q-number">{String(index+1).padStart(2,'0')}</span><span className="type-pill">{TYPE_META[q.type].label}</span>{saving&&<span className="saving">сохраняем…</span>}</div><h2>{q.prompt}</h2>{q.type==='single_choice'&&<div className="student-options">{opts.map((o:any)=><button key={o.id} className={value===o.id?'student-option selected':'student-option'} onClick={()=>onChange(o.id)}><span>{value===o.id?'●':'○'}</span>{o.text}</button>)}</div>}{q.type==='multiple_choice'&&<div className="student-options">{opts.map((o:any)=><button key={o.id} className={isSelected(o.id)?'student-option selected':'student-option'} onClick={()=>onChange(isSelected(o.id)?value.filter((x:any)=>x!==o.id):[...(Array.isArray(value)?value:[]),o.id])}><span>{isSelected(o.id)?'☑':'☐'}</span>{o.text}</button>)}</div>}{q.type==='true_false'&&<div className="segmented student"><button className={value===true?'selected':''} onClick={()=>onChange(true)}>Верно</button><button className={value===false?'selected':''} onClick={()=>onChange(false)}>Неверно</button></div>}{q.type==='fill_blank'&&<input className="answer-input" value={value??''} onChange={e=>onChange(e.target.value)} placeholder="Введите ключевое слово…"/>}{(q.type==='short_text'||q.type==='long_text')&&<textarea className="answer-input text-long" value={value??''} onChange={e=>onChange(e.target.value)} placeholder={q.data.placeholder||'Введите ответ…'}/>} {q.type==='code'&&<div className="code-answer"><div><Code2 size={15}/><span>Ответ проверит преподаватель</span></div><textarea spellCheck={false} className="answer-input code-text" value={value??''} onChange={e=>onChange(e.target.value)} placeholder="Введите код…"/></div>}{q.type==='numeric'&&<input className="answer-input" type="number" value={value??''} onChange={e=>onChange(e.target.value===''?'':Number(e.target.value))} placeholder="0"/>}{q.type==='matching'&&<div className="match-student">{(q.data.pairs||[]).map((p:any)=><div className="match-row" key={p.id}><span>{p.left}</span><select value={value?.[p.id]??''} onChange={e=>onChange({...value,[p.id]:e.target.value})}><option value="">Выберите…</option>{(q.data.pairs||[]).map((x:any)=><option key={x.id} value={x.right}>{x.right}</option>)}</select></div>)}</div>}{q.type==='ordering'&&<div className="order-student">{(Array.isArray(value)?value:(q.data.items||[]).map((x:any)=>x.id)).map((itemId:string,i:number)=>{const item=(q.data.items||[]).find((x:any)=>x.id===itemId);return <div className="order-row" key={itemId}><span>{i+1}</span><b>{item?.text||itemId}</b><button disabled={i===0} onClick={()=>{const next=[...(Array.isArray(value)?value:(q.data.items||[]).map((x:any)=>x.id))];[next[i-1],next[i]]=[next[i],next[i-1]];onChange(next)}}><ArrowUp size={13}/></button><button disabled={i===(q.data.items||[]).length-1} onClick={()=>{const next=[...(Array.isArray(value)?value:(q.data.items||[]).map((x:any)=>x.id))];[next[i+1],next[i]]=[next[i],next[i+1]];onChange(next)}}><ArrowDown size={13}/></button></div>})}</div>}</article>}

function formatDuration(seconds:number){if(seconds<=0)return'Без лимита';const m=Math.floor(seconds/60);const s=seconds%60;return s?`${m} мин ${s} сек`:`${m} мин`}
function formatClock(seconds:number){const h=Math.floor(seconds/3600);const m=Math.floor((seconds%3600)/60);const s=seconds%60;return h?`${String(h).padStart(2,'0')}:${String(m).padStart(2,'0')}:${String(s).padStart(2,'0')}`:`${String(m).padStart(2,'0')}:${String(s).padStart(2,'0')}`}
function dateShort(value:string){if(!value)return'—';const d=new Date(value);return d.toLocaleString('ru-RU',{day:'2-digit',month:'2-digit',hour:'2-digit',minute:'2-digit'})}
function csv(v:any){return`"${String(v??'').replace(/"/g,'""')}"`}
function eventLabel(type:string){const labels:any={offline:'Потеря сети',online:'Соединение восстановлено',pagehide:'Закрытие/уход со страницы',tab_hidden:'Вкладка скрыта',tab_visible:'Вкладка снова видна',heartbeat_timeout:'Heartbeat timeout',auto_submit_pending:'Ожидает автоотправки'};return labels[type]||type}

export default function App(){return <Routes><Route path="/" element={<Landing/>}/><Route path="/setup" element={<Setup/>}/><Route path="/teacher/login" element={<TeacherLogin/>}/><Route path="/join" element={<Join/>}/><Route path="/join/:code" element={<Join/>}/><Route path="/attempt/:id" element={<StudentAttempt/>}/><Route path="/teacher" element={<AuthGate><Dashboard/></AuthGate>}/><Route path="/teacher/tests/new" element={<AuthGate><NewRedirect/></AuthGate>}/><Route path="/teacher/tests/:id/edit" element={<AuthGate><Editor/></AuthGate>}/><Route path="/teacher/tests/:id/results" element={<AuthGate><Results/></AuthGate>}/><Route path="*" element={<Navigate to="/" replace/>}/></Routes>}
